package jp.tapmarker;
import java.util.*;
/** Recorded pixels with independently constructed window insets and action-coordinate checks. */
public final class AdaptiveLayoutTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static final class Runtime {
  final boolean usagi;final String prefix;final Map<String,float[]> refs;final PhaseEngine saved=new PhaseEngine(),e;final AdaptiveLayout layout;
  Runtime(boolean usagi)throws Exception{this.usagi=usagi;prefix=usagi?UsagiPreset.PREFIX:FarmPreset.P;refs=VirtualPresetProfileTest.canonical(usagi?"tests/usagi-replay.bin":"tests/farm-replay.bin");if(usagi)UsagiPreset.install(saved,refs);else FarmPreset.install(saved,refs);e=saved.runtimeCopy();layout=AdaptiveLayout.install(e,usagi?UsagiPreset.APP:FarmPreset.APP,refs,VirtualRecoveryReplayTest.evidence);check(layout!=null,"default layout available");AdCloseAutomaton.install(e,usagi?UsagiPreset.APP:FarmPreset.APP);e.strictRuntime=true;}
  Map<String,float[]> sample(VirtualPresetProfileTest.Image im,RegionSampler.Pixels pixels,long now){return layout.sample(e.activeRegions(),im.width,im.height,pixels,now);}
  PhaseEngine.Watch event(String state,VirtualPresetProfileTest.Image im,RegionSampler.Pixels pixels,long now){e.enter(prefix+state,0);Map<String,float[]> s=sample(im,pixels,now);e.observe(usagi?UsagiPreset.missionSamples(e,s):s,now);check(e.poll()==null,"first fresh frame holds visual branch");s=sample(im,pixels,now+120);e.observe(usagi?UsagiPreset.missionSamples(e,s):s,now+120);return e.poll();}
 }
 static RegionSampler.Pixels framed(VirtualPresetProfileTest.Image im,float side,float top,float bottom){return (x,y)->{float px=(x/(float)im.width-side)/(1-2*side),py=(y/(float)im.height-top)/(1-top-bottom);if(px<0||px>=1||py<0||py>=1)return 0xff101820;return im.get(Math.min(im.width-1,(int)(px*im.width)),Math.min(im.height-1,(int)(py*im.height)));};}
 static void mainScreens()throws Exception{
  for(boolean usagi:new boolean[]{true,false})for(float[] insets:new float[][]{{0,0,0},{0,.08f,.04f},{.03f,.04f,.08f},{0,.12f,0},{0,AdaptiveLayout.NORMAL_TOP,1-AdaptiveLayout.NORMAL_TOP-AdaptiveLayout.NORMAL_Y}}){Runtime r=new Runtime(usagi);VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(usagi?"usagi-main":"farm-main-pressed");RegionSampler.Pixels pixels=framed(im,insets[0],insets[1],insets[2]);PhaseEngine.Watch w=r.event("verify",im,pixels,2000);check(w!=null&&w.nextPhase.equals(r.prefix+"main"),"known game survives content insets "+usagi+" "+Arrays.toString(insets)+" / "+r.e.diagnostic+" transform="+Arrays.toString(r.layout.transform)+" identityScore="+r.layout.homeScore(new float[]{1,1,0,0},pixels)+" normalScore="+r.layout.homeScore(new float[]{1,AdaptiveLayout.NORMAL_Y,0,AdaptiveLayout.NORMAL_TOP},pixels));Map<String,float[]> s=r.sample(im,pixels,2300);float[] point=s.get(AdaptiveLayout.MAIN);float x=(insets[0]+.5f*(1-2*insets[0]))*im.width,y=(insets[1]+(usagi?.775f:.76f)*(1-insets[1]-insets[2]))*im.height;check(Math.abs(point[0]-x)<im.width*.02f&&Math.abs(point[1]-y)<im.height*.022f,"main tap follows content instead of fixed display coordinate "+usagi+" "+Arrays.toString(insets)+" expected="+x+","+y+" actual="+Arrays.toString(point)+" transform="+Arrays.toString(r.layout.transform));check(r.saved.rule(usagi?r.prefix+"return":r.prefix+"verify-home").reference.length==768,"saved reference is independent of runtime");check(Arrays.equals(r.saved.regions.get(usagi?r.prefix+"game":r.prefix+"harvest").bounds,usagi?new float[]{.66f,.082f,.77f,.112f}:new float[]{.75f,.077f,.805f,.092f}),"saved recognition bounds retained");}
  Runtime r=new Runtime(true);VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get("usagi-main");check(r.event("verify",im,im,2000)!=null,"first layout starts");check(r.event("verify",im,framed(im,0,.08f,.04f),4000)!=null,"same-size window can change its content insets without restarting");
  r.e.enter(r.prefix+"mission-tap",4200);AdInterruption interruption=new AdInterruption();for(long time:new long[]{4300,4420,7000})check(!interruption.observe(r.e,r.sample(im,framed(im,0,.08f,.04f),time),time),"a visible main screen awaiting its mission button is not misclassified as an ad");
  Map<String,float[]> samples=r.sample(im,framed(im,0,.08f,.04f),4300);PhaseEngine.Watch mission=r.e.rule(r.prefix+"ミッション中央をタップ");float[] button=AdaptiveLayout.map(r.layout.base.get(mission.regionId),r.layout.transform);samples.put(mission.regionId+AdaptiveLayout.BOUNDS,button);float[] tap=r.layout.point(mission,samples,im.width,im.height);check(tap[0]>im.width*.36f&&tap[0]<im.width*.40f&&tap[1]>im.height*.08f&&tap[1]<im.height*.13f,"mission icon tap uses the same content transform as recognition");
  float[] moved=button.clone();moved[0]+=.01f;moved[2]+=.01f;moved[1]+=.006f;moved[3]+=.006f;samples.put(mission.regionId+AdaptiveLayout.BOUNDS,moved);float[] shifted=r.layout.point(mission,samples,im.width,im.height);check(Math.abs(shifted[0]-tap[0]-im.width*.01f)<.1f&&Math.abs(shifted[1]-tap[1]-im.height*.006f)<.1f,"preflight's actual local match moves the mission tap too");
 }
 static void recordedBranches()throws Exception{
  Runtime usagi=new Runtime(true),farm=new Runtime(false);PhaseEngine.Watch w=usagi.event("main",VirtualRecoveryReplayTest.images.get("usagi-main"),VirtualRecoveryReplayTest.images.get("usagi-main"),2000);check(w==null,"506 rabbits has no false stage, mission or upgrade branch");
  for(String name:new String[]{"farm-main","farm-main-pressed"}){VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(name);w=farm.event("main",im,im,4000);check(w==null||w.nextPhase.equals(farm.prefix+"upgrade-wait"),"farm main remains the main/available shovel path: "+name);}
  for(String name:new String[]{"farm-reward","farm-reward-holdout"})for(float[] insets:new float[][]{{0,0,0},{0,.04f,.08f}}){Runtime r=new Runtime(false);VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(name);RegionSampler.Pixels pixels=framed(im,insets[0],insets[1],insets[2]);
   // Locate on the preceding main frame, as in the real game journey.
   VirtualPresetProfileTest.Image main=VirtualRecoveryReplayTest.images.get("farm-main");check(r.event("verify",main,framed(main,insets[0],insets[1],insets[2]),2000)!=null,"previous game frame calibrates window");
   w=r.event("check",im,pixels,4000);check(w!=null&&w.nextPhase.equals(r.prefix+"reward"),"coin dialog wins over game/ad fallback after calibration "+name+" "+Arrays.toString(insets)+" event="+(w==null?"null":w.id)+" diagnostic="+r.e.diagnostic+" transform="+Arrays.toString(r.layout.transform)+" distance="+r.e.rule(r.prefix+"close-tap").distance(r.sample(im,pixels,4250).get(r.prefix+"close")));w=r.event("reward",im,pixels,4300);check(w!=null&&w.action==PhaseEngine.CENTER,"close button identified from actual ROI");Map<String,float[]> s=r.sample(im,pixels,4600);float[] p=r.layout.point(w,s,im.width,im.height);float y=p[1]/im.height;check(p[0]>im.width*.4f&&p[0]<im.width*.6f&&y>insets[1]+.565f*(1-insets[1]-insets[2])&&y<insets[1]+.613f*(1-insets[1]-insets[2]),"close tap falls inside the moved individual button");}
  for(String[] row:new String[][]{{"usagi-ad-left","left"},{"farm-ad-right","right"},{"farm-ad-left","left"}}){Runtime r=new Runtime(row[0].startsWith("usagi"));VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(row[0]);w=r.event("ad",im,im,2000);check(w!=null&&AdCloseAutomaton.handles(w.regionId),"advertisement still closes the detected mark");check(r.layout.point(w,r.sample(im,im,2300),im.width,im.height)!=null,"ad coordinates are detector coordinates");}
 }
 static void negatives()throws Exception{
  for(boolean usagi:new boolean[]{true,false}){Runtime r=new Runtime(usagi);VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(usagi?"usagi-main":"farm-main");PhaseEngine.Watch home=r.e.rule(usagi?r.prefix+"return":r.prefix+"verify-home");r.e.enter(r.prefix+"verify",0);for(int part=0;part<2;part++){float[] b=part==0?(usagi?new float[]{.63f,0,.92f,.07f}:new float[]{.70f,.05f,.86f,.13f}):(usagi?new float[]{.23f,.62f,.83f,.87f}:new float[]{.34f,.61f,.74f,.85f});int[] cut=RegionMath.bounds(b,im.width,im.height);RegionSampler.Pixels missing=(x,y)->x>=cut[0]&&x<cut[2]&&y>=cut[1]&&y<cut[3]?0xff101820:im.get(x,y);Map<String,float[]> s=r.sample(im,missing,2000+part*2000);check(home.distance(s.get(home.regionId))>home.threshold,"removed header/button component blocks automatic layout admission "+usagi+" / "+part);}
   for(String name:new String[]{usagi?"usagi-ad-left":"farm-ad-left",usagi?"farm-main":"usagi-main","farm-reward-holdout"}){VirtualPresetProfileTest.Image wrong=VirtualRecoveryReplayTest.images.get(name);Map<String,float[]> s=r.sample(wrong,wrong,8000);check(home.distance(s.get(home.regionId))>home.threshold,"wrong game/ad/dimmed dialog cannot calibrate into main: "+usagi+" / "+name);}
   check(r.layout.point(r.e.rule(usagi?r.prefix+"ミッション中央をタップ":r.prefix+"close-tap"),new HashMap<>(),im.width,im.height)==null,"missing matched coordinates never fall back to a guessed preset tap");
   PhaseEngine custom=r.saved.runtimeCopy();custom.regions.get(home.regionId).bounds[0]+=.01f;check(AdaptiveLayout.install(custom,usagi?UsagiPreset.APP:FarmPreset.APP,r.refs,VirtualRecoveryReplayTest.evidence)==null,"custom primary region retained");
  }
 }
 public static void main(String[] args)throws Exception{VirtualRecoveryReplayTest.load();VirtualRecoveryReplayTest.layoutEvidence();mainScreens();recordedBranches();negatives();System.out.println("AdaptiveLayoutTest: "+checks+" checks passed; recorded previews + synthetic window insets and coordinates, no Android device execution");}
}
